# ── payroll intake: shared helpers (inlined into each node) ──
import json
import re
import datetime
import hashlib
from zoneinfo import ZoneInfo

# Knowledge layout
PR_SETTINGS = "Payroll/settings.json"
PR_CLIENTS = "Payroll/clients.json"
PR_LEDGER = "Payroll/Mail/outlook.json"
MAIL_SERVER = "m365-mail-read"
MAIL_FIRST_RUN_HOURS = 24
# Emails handled per run (oldest first); the rest wait for the next run, which starts where this one stopped.
MAIL_PER_RUN = 20
MONTHS = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]


def pr_read_json(path, default=None):
    try:
        raw = api.files.read(file=path)
    except Exception:
        return default
    try:
        return json.loads(raw)
    except Exception:
        return default


def pr_tz(settings):
    for name in (str((settings or {}).get("timezone") or ""), "Australia/Sydney"):
        try:
            if name:
                return ZoneInfo(name)
        except Exception:
            continue
    return datetime.timezone(datetime.timedelta(hours=10))


def pr_slug(name):
    return re.sub(r"[^a-z0-9]+", "-", str(name or "").lower()).strip("-")


def pr_clients(raw):
    """Payroll/clients.json as [{slug, name, other_names, senders, assignee_email}]. Senders are full addresses or
    @domain entries, lower-cased."""
    rows = raw.get("clients") if isinstance(raw, dict) else raw
    out = []
    for c in rows or []:
        if not isinstance(c, dict) or not str(c.get("name") or "").strip():
            continue
        name = str(c["name"]).strip()
        senders = [str(s or "").strip().lower() for s in c.get("senders") or [] if str(s or "").strip()]
        out.append({"slug": str(c.get("slug") or pr_slug(name)), "name": name,
                    "other_names": [str(n) for n in c.get("other_names") or [] if str(n or "").strip()],
                    "senders": senders, "assignee_email": str(c.get("assignee_email") or "").strip().lower()})
    return out


def pr_sender(value):
    """The address in "Name <address>" (or a bare address), lower-cased."""
    m = re.search(r"[\w.+'-]+@[\w-]+(\.[\w-]+)+", str(value or ""))
    return m.group(0).lower() if m else ""


def pr_client_for_sender(clients, sender):
    """The one client whose senders list this address or its domain; None when none or more than one do."""
    if not sender:
        return None
    domain = "@" + sender.split("@", 1)[1]
    hits = [c for c in clients if sender in c["senders"]]
    if not hits:
        hits = [c for c in clients if domain in c["senders"]]
    return hits[0] if len(hits) == 1 else None


def pr_when(value):
    s = str(value or "").strip()
    if not s:
        return None
    try:
        d = datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
    except ValueError:
        return None
    return d if d.tzinfo else d.replace(tzinfo=datetime.timezone.utc)


def pr_iso(when):
    return when.astimezone(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def pr_day(d):
    """05-Sep-26"""
    return "%02d-%s-%02d" % (d.day, MONTHS[d.month - 1], d.year % 100)


def pr_scrub(text):
    """Belt and braces on anything written to WorkQ: TFNs, BSBs, account and card numbers, and dollar amounts never
    leave the mailbox, whatever the AI returned."""
    s = str(text or "")
    s = re.sub(r"(?i)\b(tfn|tax file number)\b[^\n]{0,40}", "[removed]", s)
    s = re.sub(r"(?i)\b(bsb|account (no|number)|acc no)\b[^\n]{0,40}", "[removed]", s)
    s = re.sub(r"\b\d{3}[- ]?\d{3}[- ]?\d{3,}\b", "[number removed]", s)
    s = re.sub(r"\b\d{6,}\b", "[number removed]", s)
    s = re.sub(r"(A?\$|AUD)\s?\d[\d,]*(\.\d+)?", "[amount]", s)
    return s.strip()

# ── Find new emails ──
# Reads the automation owner's Outlook mailbox through m365-mail-read. Read-only: nothing in the mailbox changes.
settings = pr_read_json(PR_SETTINGS) or {}
clients = pr_clients(pr_read_json(PR_CLIENTS))
ledger = pr_read_json(PR_LEDGER) or {}
seen = ledger.get("seen") or {}
candidates = []
problem = ""
notes = []

now = datetime.datetime.now(datetime.timezone.utc)
since_dt = pr_when(ledger.get("cursor")) or (now - datetime.timedelta(hours=MAIL_FIRST_RUN_HOURS))
since = pr_iso(since_dt)

if not clients:
    problem = "no-clients"
else:
    folders = []
    for f in ["inbox"] + list(settings.get("folders") or []):
        f = str(f or "").strip().strip("/")
        if f and f.lower() not in [x.lower() for x in folders]:
            folders.append(f)
    for folder in folders:
        try:
            # One second early: emails received in the same second as the cursor are listed again and skipped as seen.
            rows = api.connectors.invoke(server=MAIL_SERVER, tool="list_emails", args={
                "folder": folder, "limit": 50, "oldestFirst": True,
                "receivedAfter": pr_iso(since_dt - datetime.timedelta(seconds=1))})
        except Exception as exc:
            notes.append("Couldn't read the " + folder + " folder: " + str(exc)[:200])
            continue
        if isinstance(rows, dict):
            rows = rows.get("value") or rows.get("emails") or rows.get("messages") or []
        for m in rows or []:
            if not isinstance(m, dict) or not m.get("id") or str(m["id"]) in seen:
                continue
            frm = m.get("from") or {}
            e = frm.get("emailAddress") if isinstance(frm, dict) else None
            e = e or (frm if isinstance(frm, dict) else {})
            sender = str(e.get("address") or pr_sender(frm)).strip().lower()
            when = pr_when(m.get("receivedDateTime"))
            candidates.append({
                "id": str(m["id"]), "folder": folder, "subject": str(m.get("subject") or "")[:300],
                "sender": sender, "sender_name": str(e.get("name") or "").strip()[:120],
                "received": pr_iso(when) if when else "", "at": when.timestamp() if when else 0,
                "preview": str(m.get("bodyPreview") or "")[:1500],
                "has_attachments": bool(m.get("hasAttachments")), "attachments": [],
            })
    candidates.sort(key=lambda m: m["at"])
    candidates = candidates[:MAIL_PER_RUN]
    # Attachment names help tell a timesheet from a newsletter (names only: nothing is downloaded).
    for m in candidates:
        if not m["has_attachments"]:
            continue
        try:
            res = api.connectors.invoke(server=MAIL_SERVER, tool="list_email_attachments", args={"id": m["id"]})
        except Exception:
            continue
        rows = (res.get("value") or res.get("attachments") or []) if isinstance(res, dict) else res
        m["attachments"] = [str(a.get("name") or "")[:120] for a in rows or [] if isinstance(a, dict) and a.get("name")][:10]

