# ── Pick out the payroll emails ──
TRIAGE_BATCH = 10
KINDS = ["timesheets", "pay changes", "new starter", "leaver", "expenses", "approval", "other payroll", "not payroll"]
TRIAGE_PROMPT = (
    "A payroll team processes pay runs for the client businesses listed in 'clients'. For each email in 'emails', say "
    "what it is: \"timesheets\" (timesheets sent, ready, approved or exported for a pay run), \"pay changes\" (notes "
    "for this pay run: changed hours, rates, allowances, bonuses, leave, deductions, corrections), \"new starter\" "
    "(a new employee, onboarding forms), \"leaver\" (a resignation or termination), \"expenses\" (reimbursements or "
    "expense files to pay with the run), \"approval\" (a client approving or querying a pay run or payment), "
    "\"other payroll\" (anything else about payroll), or \"not payroll\" (newsletters, invoices, marketing, anything "
    "unrelated). Say which client it is about: the slug of the client whose name, other names or sender matches, or "
    "an empty slug when you aren't sure (never guess). If the email names the pay period, give its last day as "
    "YYYY-MM-DD in period_end (the week or fortnight ending date), else empty. Write a one-sentence neutral summary "
    "of what the processor needs to do. The summary must NEVER contain tax file numbers, bank or account details, "
    "dates of birth, home addresses, pay rates, salaries, dollar amounts or medical information: say 'rate change "
    "for one employee', not the rate. Use first names only for employees."
)
TRIAGE_HINT = ('[{"index": 0, "kind": "timesheets", "client_slug": "acme-plumbing", "period_end": "2026-10-25", '
