                for c in pr_clients(pr_read_json(PR_CLIENTS))]
for start in range(0, len(candidates), TRIAGE_BATCH):
    batch = candidates[start:start + TRIAGE_BATCH]
    verdicts = None
    try:
        verdicts = api.ai.extract(
            prompt=TRIAGE_PROMPT,
            input=json.dumps({"clients": clients_view, "emails": [
                {"index": i, "subject": m["subject"], "from": (m["sender_name"] + " <" + m["sender"] + ">").strip(),
                 "preview": m["preview"][:800], "attachments": m["attachments"]} for i, m in enumerate(batch)]})[:20000],
            schema_hint=TRIAGE_HINT,
        )
    except Exception:
        verdicts = None
    by_index = {}
    for v in verdicts if isinstance(verdicts, list) else []:
        if isinstance(v, dict) and isinstance(v.get("index"), (int, float)):
            by_index[int(v["index"])] = v
    for i, m in enumerate(batch):
        v = by_index.get(i)
        base = {"id": m["id"], "at": m["at"]}
        if v is None:
            # No verdict (the AI call failed): try again next run.
            skipped.append(dict(base, outcome="error", reason="The AI didn't triage this email"))
            continue
        kind = str(v.get("kind") or "").strip().lower()
        if kind not in KINDS:
            kind = "other payroll"
        if kind == "not payroll":
            skipped.append(dict(base, outcome="not payroll", reason=""))
            continue
        period = str(v.get("period_end") or "").strip()
        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", period):
            period = ""
        items.append(dict(m, kind=kind, ai_client=str(v.get("client_slug") or "").strip(), period_end=period,
                          summary=pr_scrub(str(v.get("summary") or ""))[:400]))

