# ── Open or update the pay run WorkQ items ──
settings = pr_read_json(PR_SETTINGS) or {}
clients = pr_clients(pr_read_json(PR_CLIENTS))
by_slug = {c["slug"]: c for c in clients}
ledger = pr_read_json(PR_LEDGER) or {}
seen = ledger.get("seen") or {}
runs = ledger.get("runs") or {}
