now = datetime.datetime.now(datetime.timezone.utc)
today = now.astimezone(tz).date()
problem = params.get("problem") or ""
counts = {"opened": 0, "updated": 0, "unmatched": 0}
lines = list(params.get("notes") or [])
KIND_LABEL = {"timesheets": "Timesheets", "pay changes": "Pay changes", "new starter": "New starter",
              "leaver": "Leaver", "expenses": "Expenses", "approval": "Approval / query", "other payroll": "Payroll email"}

_cache = {}


def _user_id(email):
    email = str(email or "").strip().lower()
    if not email:
        return ""
    if "users" not in _cache:
        try:
            _cache["users"] = api.users.list()
        except Exception:
            _cache["users"] = []
    for u in _cache["users"] or []:
        if str(u.get("email") or "").strip().lower() == email:
            return str(u.get("id") or "")
    return ""


def _next_business_day(d):
    d = d + datetime.timedelta(days=1)
    while d.weekday() >= 5:
        d = d + datetime.timedelta(days=1)
    return d


def _open(todo_id):
    """The WorkQ item when it's still open; None when it's done, cancelled or gone."""
    try:
        t = api.workq.get(todo_id=todo_id)
    except Exception:
        return None
    if not t or str(t.get("status") or "") in ("done", "cancelled", "completed", "archived"):
        return None
    return t


def _received_text(m):
    when = pr_when(m.get("received"))
    if not when:
        return ""
    local = when.astimezone(tz)
    return pr_day(local) + " " + local.strftime("%H:%M")


def _email_block(m):
    out = ["**" + KIND_LABEL.get(m["kind"], "Payroll email") + "** email from " + (m["sender"] or "unknown sender")
           + (" · " + _received_text(m) if m.get("received") else "")]
    out.append("- **Subject:** " + pr_scrub(m["subject"]))
    if m.get("summary"):
        out.append("- **What it says:** " + m["summary"])
    if m.get("attachments"):
        out.append("- **Attachments:** " + ", ".join(pr_scrub(a) for a in m["attachments"]))
    out.append("- **Where:** Outlook, " + m.get("folder", "inbox") + " folder")
    return "\n".join(out)


def _period_text(period):
    try:
        return "w/e " + pr_day(datetime.date.fromisoformat(period))
    except ValueError:
        return "period to confirm"


def _title(client, period):
    return "Payroll · " + client["name"] + " · " + _period_text(period) if period else \
        "Payroll · " + client["name"] + " · pay run (period to confirm)"


def _assignee(client):
    uid = _user_id(client.get("assignee_email")) or _user_id(settings.get("owner_email"))
    return [uid] if uid else None


def _find_run(slug, period):
    """The open pay run item for this client and period: an exact match, else (no period in the email) the newest
    open one for the client, else one opened without a period, which the email's period then fills in."""
    key = slug + "|" + period
    if key in runs and _open(runs[key]["id"]):
        return key
    mine = sorted([k for k in runs if k.startswith(slug + "|")], key=lambda k: runs[k].get("opened") or "", reverse=True)
    if not period:
        for k in mine:
            if _open(runs[k]["id"]):
                return k
        return None
    blank = slug + "|"
    if blank in runs and _open(runs[blank]["id"]):
        # Now we know the period: retitle it and file it under that period.
        api.workq.update(todo_id=runs[blank]["id"], title=_title(by_slug[slug], period)[:200])
        runs[key] = runs.pop(blank)
        return key
    return None


def _file(m, client):
    period = m.get("period_end") or ""
    key = _find_run(client["slug"], period)
    if key:
        api.workq.comment(todo_id=runs[key]["id"], body=_email_block(m))
        counts["updated"] += 1
        return
    desc = "\n".join([
        "**What to do:** Process this pay run. Payroll emails for it are added below as comments as they arrive.",
        "",
        "- **Client:** " + client["name"],
        "- **Pay period:** " + _period_text(period),
        "- **Opened by:** Payroll email intake (Outlook)",
        "",
        "**First email**",
        "",
        _email_block(m),
    ])
    t = api.workq.create(
        title=_title(client, period)[:200], scope="org", description=desc, priority="high",
        due_date=str(_next_business_day(today)), assignee_ids=_assignee(client),
        labels=["payroll", "pay-run", "email-intake"],
    )
    runs[client["slug"] + "|" + period] = {"id": str(t.get("id") or ""), "opened": pr_iso(now), "client": client["name"]}
    counts["opened"] += 1


def _unmatched(m):
    desc = "\n".join([
        "**What to do:** This looks like a payroll email, but it couldn't be matched to one client, so it wasn't "
        "filed. Check which client it's for and handle it. To have the next one filed automatically, add the "
        "sender's address (or @domain) to that client's \"senders\" in Knowledge, Payroll/clients.json.",
        "",
        _email_block(m),
    ])
    owner = _user_id(settings.get("owner_email"))
    api.workq.create(
        title=("Payroll email needs a client: " + pr_scrub(m["subject"]))[:200], scope="org", description=desc,
        priority="medium", due_date=str(_next_business_day(today)), assignee_ids=[owner] if owner else None,
        labels=["payroll", "email-intake", "needs-client"],
    )
    counts["unmatched"] += 1


if problem == "no-clients":
    if not ledger.get("setup_asked"):
        api.workq.create(
            title="Set up payroll email intake", scope="org", priority="medium",
            due_date=str(_next_business_day(today)), labels=["payroll", "email-intake", "setup"],
            description="\n".join([
                "**What to do:** Add the payroll client list to Knowledge so the intake knows whose emails are whose. "
                "No emails are read until it exists.",
                "",
                "- **File:** Payroll/clients.json (organisation Knowledge)",
                "- **Shape:** a list of clients, each with \"name\", \"senders\" (addresses or @domains the client's "
                "payroll emails come from), and optionally \"other_names\" and \"assignee_email\".",
                "- **Optional settings:** Payroll/settings.json with \"owner_email\" (who gets items that need a "
                "person), \"folders\" (extra Outlook folders to read) and \"timezone\".",
            ]),
        )
        ledger["setup_asked"] = pr_iso(now)
        lines.append("Asked for the payroll client list (Payroll/clients.json).")
else:
    newest = pr_when(ledger.get("cursor"))
    for s in params.get("skipped") or []:
        if s.get("outcome") == "error":
            errors[s["id"]] = int(errors.get(s["id"]) or 0) + 1
            if errors[s["id"]] < 3:
                continue
            lines.append("Gave up on one email after 3 tries: " + str(s.get("reason") or ""))
        seen[s["id"]] = {"at": pr_iso(now), "outcome": s.get("outcome") or ""}
    for m in params.get("items") or []:
        client = pr_client_for_sender(clients, m["sender"]) or by_slug.get(m.get("ai_client") or "")
        try:
            if client:
                _file(m, client)
                outcome = "filed"
            else:
                _unmatched(m)
                outcome = "needs client"
        except Exception as exc:
            errors[m["id"]] = int(errors.get(m["id"]) or 0) + 1
            lines.append("Couldn't file \"" + pr_scrub(m["subject"])[:80] + "\": " + str(exc)[:200])
            if errors[m["id"]] < 3:
                continue
            outcome = "error"
        seen[m["id"]] = {"at": pr_iso(now), "outcome": outcome, "client": client["slug"] if client else ""}
    # The cursor moves to the newest email that's settled, but never past one still waiting for a retry.
    waiting = [s.get("at") or 0 for s in (params.get("skipped") or []) + (params.get("items") or [])
               if s["id"] not in seen and (s.get("at") or 0) > 0]
    settled = [s.get("at") or 0 for s in (params.get("skipped") or []) + (params.get("items") or [])
               if s["id"] in seen and (s.get("at") or 0) > 0]
    if settled:
        limit = min(waiting) - 1 if waiting else max(settled)
        best = max([a for a in settled if a <= limit] or [0])
        if best and (not newest or best > newest.timestamp()):
            ledger["cursor"] = pr_iso(datetime.datetime.fromtimestamp(best, datetime.timezone.utc))
    if not ledger.get("cursor"):
        ledger["cursor"] = params.get("since") or pr_iso(now)
    # Keep the ledger small: forget emails handled more than 30 days ago.
    cutoff = pr_iso(now - datetime.timedelta(days=30))
    seen = {k: v for k, v in seen.items() if str((v or {}).get("at") or "") >= cutoff}
    errors = {k: v for k, v in errors.items() if k not in seen}
    runs = {k: v for k, v in runs.items() if str(v.get("opened") or "") >= pr_iso(now - datetime.timedelta(days=90))}

ledger.update({"seen": seen, "runs": runs, "errors": errors, "last_run": pr_iso(now)})
api.files.put(file=PR_LEDGER, content=json.dumps(ledger, indent=2, sort_keys=True))
summary = (str(counts["opened"]) + " pay run item(s) opened, " + str(counts["updated"]) + " updated, " + str(counts["unmatched"])
           + " email(s) need a client") + ("" if not lines else ". " + " ".join(lines))
